   682→        }
   683→
   684→        function closeSidebar() {
   685→            document.getElementById('sidebar').classList.remove('open');
   686→            document.getElementById('sidebarOverlay').classList.remove('open');
   687→        }
   688→
   689→        let projects = [];
   690→        let currentProject = null;
   691→        let conversations = {};
   692→        let currentConversation = null;
   693→        let currentMessage = null;
   694→
   695→        const listContainer = document.getElementById('listContainer');
   696→        const messagesContainer = document.getElementById('messagesContainer');
   697→        const conversationHeader = document.getElementById('conversationHeader');
   698→
   699→        // URL state management - use short project names in URLs
   700→        function getShortProjectName(fullName) {
   701→            const match = fullName.match(/-Desktop-(.+)$/);
   702→            return match ? match[1] : fullName.split('-').pop();
   703→        }
   704→
   705→        function getFullProjectName(shortName) {
   706→            // Find project by short name
   707→            const project = projects.find(p => getShortProjectName(p.name) === shortName);
   708→            return project ? project.name : shortName;
   709→        }
   710→
   711→        function updateUrl() {
   712→            const params = new URLSearchParams();
   713→            if (currentProject) params.set('project', getShortProjectName(currentProject));
   714→            if (currentConversation) params.set('session', currentConversation);
   715→            if (currentMessage) params.set('msg', currentMessage);
   716→            const newUrl = params.toString() ? `?${params.toString()}` : window.location.pathname;
   717→            history.pushState({project: currentProject, session: currentConversation, message: currentMessage}, '', newUrl);
   718→        }
   719→
   720→        function loadFromUrl() {
