  1314→        function renderToolResult(toolResult, msgUuid) {
  1315→            let content = '';
  1316→            let rawContent = '';
  1317→
  1318→            if (typeof toolResult.content === 'string') {
  1319→                content = escapeHtml(toolResult.content);
  1320→                rawContent = toolResult.content;
  1321→            } else if (Array.isArray(toolResult.content)) {
  1322→                content = toolResult.content.map(c => {
  1323→                    if (c.type === 'image' && c.source) {
  1324→                        const src = c.source.type === 'base64'
  1325→                            ? `data:${c.source.media_type};base64,${c.source.data}`
  1326→                            : c.source.url;
  1327→                        return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
  1328→                    }
  1329→                    if (c.text) rawContent += c.text;
  1330→                    return c.text ? escapeHtml(c.text) : '';
  1331→                }).join('\n');
  1332→            }
  1333→
  1334→            const isError = toolResult.is_error === true;
  1335→            const errorClass = isError ? ' error' : '';
  1336→            const headerText = isError ? 'Hook Error' : 'Output';
  1337→
  1338→            let resultHtml = `<div class="tool-result${errorClass}"><div class="tool-result-header">${headerText}</div><div class="tool-result-content">${content}</div></div>`;
  1339→
  1340→            // Check if this is a Task tool result - if so, insert agent inline
  1341→            const toolUseId = toolResult.tool_use_id;
  1342→            const toolInfo = toolUseMap[toolUseId];
  1343→            if (toolInfo && toolInfo.name === 'Task') {
  1344→                // Try to find matching agent by looking for agent ID in the result
  1345→                // Task results often contain "Agent ID: xxx" or similar
  1346→                const agentIdMatch = rawContent.match(/agent[_-]?(?:id)?[:\s]*([a-f0-9]{8})/i) ||
  1347→                                     rawContent.match(/([a-f0-9]{8})/);
  1348→
  1349→                // Also try to match by finding any unrendered agent
  1350→                let matchedAgentId = null;
  1351→                if (agentIdMatch) {
  1352→                    const potentialId = agentIdMatch[1];
  1353→                    if (loadedAgentConversations[potentialId] && !renderedAgents.has(potentialId)) {
  1354→                        matchedAgentId = potentialId;
  1355→                    }
  1356→                }
  1357→
  1358→                // If no match by ID, try to get next unrendered agent in order
  1359→                if (!matchedAgentId) {
  1360→                    for (const agentId of Object.keys(loadedAgentConversations)) {
  1361→                        if (!renderedAgents.has(agentId)) {
  1362→                            matchedAgentId = agentId;
  1363→                            break;
  1364→                        }
  1365→                    }
  1366→                }
  1367→
  1368→                if (matchedAgentId && loadedAgentConversations[matchedAgentId]) {
  1369→                    renderedAgents.add(matchedAgentId);
  1370→                    resultHtml += renderAgentInline(matchedAgentId, loadedAgentConversations[matchedAgentId], msgUuid);
  1371→                }
  1372→            }
  1373→
  1374→            return resultHtml;
  1375→        }
